CREATE DATABASE IF NOT EXISTS aquasync_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aquasync_db;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role ENUM('customer','admin','rider') NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE water_stations (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, address TEXT NOT NULL, phone VARCHAR(30), payment_instructions TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE customers (user_id INT PRIMARY KEY, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE riders (user_id INT PRIMARY KEY, station_id INT NOT NULL, availability ENUM('Available','Busy','Offline') DEFAULT 'Available', FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(station_id) REFERENCES water_stations(id));
CREATE TABLE delivery_areas (id INT AUTO_INCREMENT PRIMARY KEY, station_id INT NOT NULL, barangay VARCHAR(100) NOT NULL UNIQUE, fee DECIMAL(10,2) NOT NULL DEFAULT 0, active BOOLEAN DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(station_id) REFERENCES water_stations(id));
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, station_id INT NOT NULL, name VARCHAR(100) NOT NULL, description TEXT, price DECIMAL(10,2) NOT NULL, active BOOLEAN DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(station_id) REFERENCES water_stations(id));
CREATE TABLE addresses (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, address TEXT NOT NULL, barangay VARCHAR(100) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE subscriptions (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, address_id INT NOT NULL, quantity INT NOT NULL, frequency VARCHAR(30) DEFAULT 'Weekly', selected_days VARCHAR(30) NOT NULL, preferred_time TIME NOT NULL, payment_method ENUM('COD','GCash','Maya') NOT NULL, start_date DATE NOT NULL, next_delivery_date DATE NOT NULL, status ENUM('Active','Paused','Cancelled') DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,next_delivery_date), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(address_id) REFERENCES addresses(id));
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(30) UNIQUE, customer_id INT NOT NULL, station_id INT NOT NULL, subscription_id INT, subscription_date DATE, quantity INT NOT NULL, gallon_price DECIMAL(10,2) NOT NULL, delivery_fee DECIMAL(10,2) NOT NULL, total DECIMAL(10,2) NOT NULL, address TEXT NOT NULL, barangay VARCHAR(100) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), payment_method ENUM('COD','GCash','Maya') NOT NULL, status ENUM('Pending','Confirmed','Preparing','Assigned','Out for Delivery','Delivered','Cancelled') DEFAULT 'Pending', rider_id INT, picked_up_at DATETIME, scheduled_at DATETIME NOT NULL, delivered_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(subscription_id,subscription_date), INDEX(status,scheduled_at), INDEX(customer_id,delivered_at), INDEX(barangay,scheduled_at), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(station_id) REFERENCES water_stations(id), FOREIGN KEY(subscription_id) REFERENCES subscriptions(id), FOREIGN KEY(rider_id) REFERENCES riders(user_id));
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL UNIQUE, payment_method ENUM('COD','GCash','Maya') NOT NULL, amount DECIMAL(10,2) NOT NULL, payment_reference VARCHAR(100), payment_status ENUM('Pending','Paid','Failed','Refunded') DEFAULT 'Pending', paid_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE rider_locations (rider_id INT PRIMARY KEY, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(rider_id) REFERENCES riders(user_id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message TEXT NOT NULL, dedupe_key VARCHAR(100) UNIQUE, read_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,read_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE feedback (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL UNIQUE, customer_id INT NOT NULL, rating INT NOT NULL, comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE order_status_history (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, actor_id INT NOT NULL, status VARCHAR(30) NOT NULL, note VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_id) REFERENCES users(id));
